  invalidValue: (p) => {
    switch (p.reason) {
      case "valueMissing":
        return "Bu alan\u0131 doldurun.";
      case "typeMismatch":
        return p.type === "email" ? "Ge\xE7erli bir e-posta adresi girin." : p.type === "url" ? "Ge\xE7erli bir URL girin." : "Ge\xE7erli bir de\u011Fer girin.";
      case "badInput":
        return "Bir say\u0131 girin.";
      case "tooShort":
        return "En az " + p.minLength + " karakter (\u015Fu an " + p.length + ").";
      case "tooLong":
        return "En fazla " + p.maxLength + " karakter (\u015Fu an " + p.length + ").";
      case "rangeUnderflow":
        return "De\u011Fer " + p.min + " veya daha b\xFCy\xFCk olmal\u0131.";
      case "rangeOverflow":
        return "De\u011Fer " + p.max + " veya daha k\xFC\xE7\xFCk olmal\u0131.";
      case "stepMismatch":
        return p.step + " say\u0131s\u0131n\u0131n bir kat\u0131n\u0131 girin.";
      case "patternMismatch":
        return "\u0130stenen bi\xE7ime uyun." + (p.title ? " " + p.title : "");
      default:
        return "";
    }
  },
